# UPDATE: adds FBX export. Paste into a NEW cell and run it (app stays on the same link).
import os, json, subprocess, time
BUNDLE = json.loads("{\"app.py\": \"\\\"\\\"\\\"Batch 2D image -> 3D model web app. Run: uvicorn app:app --port 8000\\\"\\\"\\\"\\nimport io\\nimport os\\nimport queue\\nimport shutil\\nimport threading\\nimport uuid\\nimport zipfile\\nfrom pathlib import Path\\n\\nfrom fastapi import FastAPI, File, HTTPException, UploadFile\\nfrom fastapi.responses import FileResponse, StreamingResponse\\nfrom fastapi.staticfiles import StaticFiles\\n\\nfrom providers import get_provider\\nfrom convert import glb_to_fbx\\n\\nDATA = Path(os.environ.get(\\\"DATA_DIR\\\", Path(__file__).parent / \\\"data\\\"))\\nIN_DIR, OUT_DIR = DATA / \\\"inputs\\\", DATA / \\\"outputs\\\"\\nfor d in (IN_DIR, OUT_DIR):\\n    d.mkdir(parents=True, exist_ok=True)\\n\\nALLOWED = {\\\".png\\\", \\\".jpg\\\", \\\".jpeg\\\", \\\".webp\\\", \\\".bmp\\\"}\\nMAX_BYTES = 25 * 1024 * 1024\\n\\napp = FastAPI(title=\\\"img23d\\\")\\njobs: dict[str, dict] = {}\\norder: list[str] = []\\nq: \\\"queue.Queue[str]\\\" = queue.Queue()\\nprovider = None\\n\\n\\ndef worker():\\n    global provider\\n    while True:\\n        job_id = q.get()\\n        job = jobs.get(job_id)\\n        if not job or job[\\\"status\\\"] == \\\"cancelled\\\":\\n            continue\\n        try:\\n            if provider is None:\\n                job[\\\"status\\\"] = \\\"loading model\\\"\\n                provider = get_provider()\\n            job[\\\"status\\\"] = \\\"processing\\\"\\n            provider.generate(job[\\\"input\\\"], job[\\\"output\\\"])\\n            job[\\\"status\\\"] = \\\"done\\\"\\n        except Exception as e:  # keep the batch going\\n            job[\\\"status\\\"] = \\\"failed\\\"\\n            job[\\\"error\\\"] = f\\\"{type(e).__name__}: {e}\\\"\\n        finally:\\n            q.task_done()\\n\\n\\nthreading.Thread(target=worker, daemon=True).start()\\n\\n\\ndef public(job):\\n    return {k: job[k] for k in (\\\"id\\\", \\\"name\\\", \\\"status\\\", \\\"error\\\")}\\n\\n\\n@app.post(\\\"/api/upload\\\")\\nasync def upload(files: list[UploadFile] = File(...)):\\n    created = []\\n    for f in files:\\n        ext = Path(f.filename or \\\"\\\").suffix.lower()\\n        if ext not in ALLOWED:\\n            created.append({\\\"name\\\": f.filename, \\\"status\\\": \\\"failed\\\", \\\"error\\\": \\\"unsupported file type\\\", \\\"id\\\": uuid.uuid4().hex})\\n            continue\\n        data = await f.read()\\n        if len(data) > MAX_BYTES:\\n            created.append({\\\"name\\\": f.filename, \\\"status\\\": \\\"failed\\\", \\\"error\\\": \\\"file too large (25MB max)\\\", \\\"id\\\": uuid.uuid4().hex})\\n            continue\\n        job_id = uuid.uuid4().hex\\n        inp = IN_DIR / f\\\"{job_id}{ext}\\\"\\n        inp.write_bytes(data)\\n        job = {\\\"id\\\": job_id, \\\"name\\\": Path(f.filename).name, \\\"status\\\": \\\"queued\\\", \\\"error\\\": None,\\n               \\\"input\\\": str(inp), \\\"output\\\": str(OUT_DIR / f\\\"{job_id}.glb\\\")}\\n        jobs[job_id] = job\\n        order.append(job_id)\\n        q.put(job_id)\\n        created.append(public(job))\\n    return created\\n\\n\\n@app.get(\\\"/api/jobs\\\")\\ndef list_jobs():\\n    return [public(jobs[i]) for i in order if i in jobs]\\n\\n\\ndef get_job(job_id):\\n    if job_id not in jobs:\\n        raise HTTPException(404, \\\"no such job\\\")\\n    return jobs[job_id]\\n\\n\\n@app.get(\\\"/api/jobs/{job_id}/model.glb\\\")\\ndef model(job_id: str):\\n    job = get_job(job_id)\\n    if job[\\\"status\\\"] != \\\"done\\\":\\n        raise HTTPException(409, \\\"not ready\\\")\\n    return FileResponse(job[\\\"output\\\"], media_type=\\\"model/gltf-binary\\\",\\n                        filename=Path(job[\\\"name\\\"]).stem + \\\".glb\\\")\\n\\n\\ndef fbx_path(job):\\n    fbx = Path(job[\\\"output\\\"]).with_suffix(\\\".fbx\\\")\\n    if not fbx.exists():\\n        try:\\n            glb_to_fbx(job[\\\"output\\\"], str(fbx))\\n        except Exception as e:\\n            raise HTTPException(500, str(e))\\n    return fbx\\n\\n\\n@app.get(\\\"/api/jobs/{job_id}/model.fbx\\\")\\ndef model_fbx(job_id: str):\\n    job = get_job(job_id)\\n    if job[\\\"status\\\"] != \\\"done\\\":\\n        raise HTTPException(409, \\\"not ready\\\")\\n    return FileResponse(fbx_path(job), media_type=\\\"application/octet-stream\\\",\\n                        filename=Path(job[\\\"name\\\"]).stem + \\\".fbx\\\")\\n\\n\\n@app.get(\\\"/api/jobs/{job_id}/input\\\")\\ndef job_input(job_id: str):\\n    return FileResponse(get_job(job_id)[\\\"input\\\"])\\n\\n\\n@app.post(\\\"/api/jobs/{job_id}/retry\\\")\\ndef retry(job_id: str):\\n    job = get_job(job_id)\\n    if job[\\\"status\\\"] == \\\"failed\\\" and Path(job[\\\"input\\\"]).exists():\\n        job.update(status=\\\"queued\\\", error=None)\\n        q.put(job_id)\\n    return public(job)\\n\\n\\n@app.delete(\\\"/api/jobs/{job_id}\\\")\\ndef delete(job_id: str):\\n    job = get_job(job_id)\\n    job[\\\"status\\\"] = \\\"cancelled\\\"\\n    for p in (job[\\\"input\\\"], job[\\\"output\\\"], Path(job[\\\"output\\\"]).with_suffix(\\\".fbx\\\")):\\n        Path(p).unlink(missing_ok=True)\\n    jobs.pop(job_id, None)\\n    if job_id in order:\\n        order.remove(job_id)\\n    return {\\\"ok\\\": True}\\n\\n\\n@app.get(\\\"/api/download.zip\\\")\\ndef download_all(fmt: str = \\\"glb\\\"):\\n    buf = io.BytesIO()\\n    seen = {}\\n    with zipfile.ZipFile(buf, \\\"w\\\", zipfile.ZIP_STORED) as z:\\n        for i in order:\\n            j = jobs.get(i)\\n            if j and j[\\\"status\\\"] == \\\"done\\\":\\n                stem = Path(j[\\\"name\\\"]).stem\\n                seen[stem] = seen.get(stem, 0) + 1\\n                name = stem if seen[stem] == 1 else f\\\"{stem}_{seen[stem]}\\\"\\n                if fmt == \\\"fbx\\\":\\n                    z.write(fbx_path(j), name + \\\".fbx\\\")\\n                else:\\n                    z.write(j[\\\"output\\\"], name + \\\".glb\\\")\\n    buf.seek(0)\\n    return StreamingResponse(buf, media_type=\\\"application/zip\\\",\\n                             headers={\\\"Content-Disposition\\\": 'attachment; filename=\\\"models.zip\\\"'})\\n\\n\\napp.mount(\\\"/\\\", StaticFiles(directory=Path(__file__).parent / \\\"static\\\", html=True), name=\\\"static\\\")\\n\", \"convert.py\": \"\\\"\\\"\\\"GLB -> FBX using headless Blender (apt install blender).\\\"\\\"\\\"\\nimport shutil\\nimport subprocess\\nimport tempfile\\nfrom pathlib import Path\\n\\nSCRIPT = \\\"\\\"\\\"\\nimport bpy, sys\\na = sys.argv[sys.argv.index('--') + 1:]\\nbpy.ops.wm.read_factory_settings(use_empty=True)\\nbpy.ops.import_scene.gltf(filepath=a[0])\\nbpy.ops.export_scene.fbx(filepath=a[1], path_mode='COPY', embed_textures=True, add_leaf_bones=False)\\n\\\"\\\"\\\"\\n\\n\\ndef blender_available() -> bool:\\n    return shutil.which(\\\"blender\\\") is not None\\n\\n\\ndef glb_to_fbx(glb: str, fbx: str) -> None:\\n    exe = shutil.which(\\\"blender\\\")\\n    if not exe:\\n        raise RuntimeError(\\\"Blender is not installed (run: apt-get install -y blender)\\\")\\n    with tempfile.NamedTemporaryFile(\\\"w\\\", suffix=\\\".py\\\", delete=False) as f:\\n        f.write(SCRIPT)\\n        script = f.name\\n    try:\\n        r = subprocess.run([exe, \\\"-b\\\", \\\"-noaudio\\\", \\\"-P\\\", script, \\\"--\\\", glb, fbx],\\n                           capture_output=True, text=True, timeout=300)\\n        if not Path(fbx).exists():\\n            raise RuntimeError(\\\"FBX conversion failed: \\\" + (r.stderr or r.stdout)[-400:])\\n    finally:\\n        Path(script).unlink(missing_ok=True)\\n\", \"static/index.html\": \"<!doctype html>\\n<html lang=\\\"en\\\">\\n<head>\\n<meta charset=\\\"utf-8\\\">\\n<meta name=\\\"viewport\\\" content=\\\"width=device-width, initial-scale=1\\\">\\n<title>Image to 3D Batch</title>\\n<script type=\\\"module\\\" src=\\\"https://cdnjs.cloudflare.com/ajax/libs/model-viewer/3.5.0/model-viewer.min.js\\\"></script>\\n<style>\\n  :root { --bg:#f6f7f9; --card:#fff; --text:#1c1f24; --muted:#6b7280; --accent:#4f46e5; --border:#e3e5e9; --bad:#dc2626; --ok:#16a34a; }\\n  @media (prefers-color-scheme: dark) { :root { --bg:#14161a; --card:#1d2025; --text:#e8eaed; --muted:#9aa0a8; --border:#2c3037; } }\\n  * { box-sizing:border-box } body { margin:0; font:15px system-ui,sans-serif; background:var(--bg); color:var(--text); }\\n  main { max-width:1100px; margin:0 auto; padding:24px 16px 64px; }\\n  h1 { font-size:22px; margin:0 0 4px } p.sub { color:var(--muted); margin:0 0 20px }\\n  #drop { border:2px dashed var(--border); border-radius:12px; padding:36px 16px; text-align:center; background:var(--card); cursor:pointer; }\\n  #drop.over { border-color:var(--accent); } #drop b { color:var(--accent) }\\n  .bar { display:flex; gap:12px; align-items:center; margin:20px 0 12px; flex-wrap:wrap }\\n  .bar span { color:var(--muted); flex:1 }\\n  button { background:var(--accent); color:#fff; border:0; border-radius:8px; padding:8px 14px; font:inherit; cursor:pointer }\\n  button.ghost { background:transparent; color:var(--text); border:1px solid var(--border) }\\n  button:disabled { opacity:.45; cursor:default }\\n  #grid { display:grid; grid-template-columns:repeat(auto-fill,minmax(240px,1fr)); gap:14px }\\n  .card { background:var(--card); border:1px solid var(--border); border-radius:12px; overflow:hidden; display:flex; flex-direction:column }\\n  .view { height:220px; background:var(--bg); display:flex; align-items:center; justify-content:center; position:relative }\\n  .view img { max-width:100%; max-height:100%; object-fit:contain; opacity:.6 }\\n  model-viewer { width:100%; height:100%; --poster-color:transparent }\\n  .meta { padding:10px 12px; display:flex; flex-direction:column; gap:6px }\\n  .name { font-weight:600; overflow:hidden; text-overflow:ellipsis; white-space:nowrap }\\n  .status { font-size:13px; color:var(--muted) } .status.done { color:var(--ok) } .status.failed { color:var(--bad) }\\n  .row { display:flex; gap:6px } .row button { padding:5px 10px; font-size:13px }\\n</style>\\n</head>\\n<body>\\n<main>\\n  <h1>Image \\u2192 3D Batch</h1>\\n  <p class=\\\"sub\\\">Drop as many images as you like. Each becomes a 3D model (.glb) you can preview and download.</p>\\n  <div id=\\\"drop\\\"><b>Click to choose</b> or drag images here\\n    <input id=\\\"file\\\" type=\\\"file\\\" accept=\\\"image/*\\\" multiple hidden></div>\\n  <div class=\\\"bar\\\"><span id=\\\"summary\\\">No images yet</span>\\n    <button class=\\\"ghost\\\" id=\\\"clear\\\">Clear finished</button>\\n    <button id=\\\"zip\\\" disabled>All .glb (.zip)</button>\\n    <button id=\\\"zipfbx\\\" disabled>All .fbx (.zip)</button></div>\\n  <div id=\\\"grid\\\"></div>\\n</main>\\n<script>\\nconst $ = s => document.querySelector(s), drop = $('#drop'), file = $('#file'), grid = $('#grid');\\ndrop.onclick = () => file.click();\\nfile.onchange = () => upload(file.files);\\n['dragover','dragenter'].forEach(e => drop.addEventListener(e, ev => { ev.preventDefault(); drop.classList.add('over'); }));\\n['dragleave','drop'].forEach(e => drop.addEventListener(e, ev => { ev.preventDefault(); drop.classList.remove('over'); }));\\ndrop.addEventListener('drop', ev => upload(ev.dataTransfer.files));\\n$('#zip').onclick = () => location.href = '/api/download.zip';\\n$('#zipfbx').onclick = () => location.href = '/api/download.zip?fmt=fbx';\\n$('#clear').onclick = async () => { for (const j of jobs) if (j.status === 'done' || j.status === 'failed') await fetch('/api/jobs/' + j.id, {method:'DELETE'}); poll(); };\\n\\nasync function upload(files) {\\n  const BATCH = 10;                       // upload in chunks so big batches stay reliable\\n  const list = [...files];\\n  for (let i = 0; i < list.length; i += BATCH) {\\n    const fd = new FormData();\\n    list.slice(i, i + BATCH).forEach(f => fd.append('files', f));\\n    await fetch('/api/upload', {method:'POST', body:fd});\\n    poll();\\n  }\\n  file.value = '';\\n}\\n\\nlet jobs = [], built = {};\\nfunction el(tag, cls, text) { const e = document.createElement(tag); if (cls) e.className = cls; if (text) e.textContent = text; return e; }\\n\\nfunction render() {\\n  const ids = new Set(jobs.map(j => j.id));\\n  for (const id in built) if (!ids.has(id)) { built[id].card.remove(); delete built[id]; }\\n  for (const j of jobs) {\\n    let b = built[j.id];\\n    if (!b) {\\n      const card = el('div','card'), view = el('div','view'), meta = el('div','meta');\\n      const img = el('img'); img.src = `/api/jobs/${j.id}/input`; view.append(img);\\n      const name = el('div','name', j.name), status = el('div','status'), row = el('div','row');\\n      meta.append(name, status, row); card.append(view, meta); grid.append(card);\\n      b = built[j.id] = {card, view, status, row, shown:null};\\n    }\\n    b.status.textContent = j.status + (j.error ? ': ' + j.error : '');\\n    b.status.className = 'status ' + j.status;\\n    if (b.shown !== j.status) {\\n      b.shown = j.status; b.row.replaceChildren();\\n      if (j.status === 'done') {\\n        const mv = document.createElement('model-viewer');\\n        mv.src = `/api/jobs/${j.id}/model.glb`; mv.setAttribute('camera-controls',''); mv.setAttribute('auto-rotate','');\\n        mv.setAttribute('shadow-intensity','1'); b.view.replaceChildren(mv);\\n        const dl = el('button','', 'Download .glb'); dl.onclick = () => location.href = mv.src; b.row.append(dl);\\n        const fb = el('button','', 'Download .fbx'); fb.onclick = () => location.href = `/api/jobs/${j.id}/model.fbx`; b.row.append(fb);\\n      }\\n      if (j.status === 'failed') { const r = el('button','','Retry'); r.onclick = async () => { await fetch(`/api/jobs/${j.id}/retry`, {method:'POST'}); poll(); }; b.row.append(r); }\\n      if (j.status !== 'processing' && j.status !== 'loading model') {\\n        const d = el('button','ghost','Remove'); d.onclick = async () => { await fetch('/api/jobs/' + j.id, {method:'DELETE'}); poll(); }; b.row.append(d);\\n      }\\n    }\\n  }\\n  const done = jobs.filter(j => j.status === 'done').length, failed = jobs.filter(j => j.status === 'failed').length;\\n  $('#summary').textContent = jobs.length ? `${done} of ${jobs.length} done` + (failed ? `, ${failed} failed` : '') : 'No images yet';\\n  $('#zip').disabled = $('#zipfbx').disabled = !done;\\n}\\nasync function poll() { try { jobs = await (await fetch('/api/jobs')).json(); render(); } catch (e) {} }\\nsetInterval(poll, 1500); poll();\\n</script>\\n</body>\\n</html>\\n\"}")
for path, text in BUNDLE.items():
    full = os.path.join('/content/img23d', path)
    os.makedirs(os.path.dirname(full), exist_ok=True)
    open(full, 'w').write(text)
